# DK NVX.  Næstved Vest - Næstved Øst
#
let nn = path("d3.dk.nvx");

with detail = 3, railway = :first :pax :removed {
    with link = "line.dk.NVX" {
        track(:ror,
                nn[:nav + 0.9dl, :nav + 1dl] >> 0.5md << 0.5mt
            ..  nn[:nas.xr - 300m, :nas.xr + 0.1dl] << 1ms << 1mt
        );
        track(:ror, nn[:nas.xr, :nao - 1dl] << 1ms << 1mt);
    }
}

